package africa.growtogether.platform.ewe.task; import static org.junit.jupiter.api.Assertions.*; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test;
class WorkflowTaskTest { @Test void approvalLifecycle(){WorkflowTask t=new WorkflowTask(UUID.randomUUID(),"principal_approval","Principal approval",TaskType.APPROVAL);t.assignRole("school_principal");t.claim(UUID.randomUUID());t.start();t.decide(ApprovalDecision.APPROVE,"Approved");assertEquals(TaskStatus.COMPLETED,t.getTaskStatus());assertEquals("APPROVE",t.getOutcome());} @Test void escalationBeforeDueRejected(){WorkflowTask t=new WorkflowTask(UUID.randomUUID(),"review","Review",TaskType.REVIEW);assertThrows(IllegalArgumentException.class,()->t.setSla(Instant.now().plusSeconds(60),Instant.now()));} @Test void delegationChangesAssignee(){WorkflowTask t=new WorkflowTask(UUID.randomUUID(),"review","Review",TaskType.HUMAN);UUID a=UUID.randomUUID(),b=UUID.randomUUID();t.assignUser(a);t.delegate(a,b);assertEquals(b,t.getAssigneeUserId());assertEquals(a,t.getDelegatedFrom());}}
